   252→        set({ playbackState: 'paused' });
   253→      } else {
   254→        set({ playbackState: 'playing' });
   255→      }
   256→    },
   257→
   258→    setCurrentFrameIndex: (currentFrameIndex) => set({ currentFrameIndex }),
