   343→    cutFrames: (frameIds) => set({ clipboardFrameIds: frameIds, clipboardOperation: 'cut' }),
   344→    clearClipboard: () => set({ clipboardFrameIds: [], clipboardOperation: null }),
   345→    hasClipboardContent: () => get().clipboardFrameIds.length > 0,
   346→
   347→    // History
   348→    setCanUndo: (canUndo) => set({ canUndo }),
   349→    setCanRedo: (canRedo) => set({ canRedo }),
   350→    setHistoryIndex: (historyIndex) => set({ historyIndex }),
   351→
   352→    // UI
   353→    toggleSidebar: () => set((state) => ({ isSidebarCollapsed: !state.isSidebarCollapsed })),
   354→    toggleTimeline: () => set((state) => ({ isTimelineCollapsed: !state.isTimelineCollapsed })),
   355→    setActivePanel: (activePanel) => set({ activePanel }),
   356→
   357→    // Onion skin
   358→    setShowOnionSkin: (showOnionSkin) => set({ showOnionSkin }),
   359→    setOnionSkinFramesBefore: (onionSkinFramesBefore) => set({ onionSkinFramesBefore }),
   360→    setOnionSkinFramesAfter: (onionSkinFramesAfter) => set({ onionSkinFramesAfter }),
   361→    setOnionSkinOpacity: (onionSkinOpacity) => set({ onionSkinOpacity }),
   362→
   363→    // Reset
