   366→);
   367→
   368→// Selector hooks
   369→export const selectIsPlaying = (state: EditorState) => state.playbackState === 'playing';
   370→export const selectSelectedFrameCount = (state: EditorState) => state.selectedFrameIds.length;
   371→export const selectHasSelection = (state: EditorState) => state.selectedFrameIds.length > 0;
