     1→import { useEffect, useRef, type ReactNode, type KeyboardEvent } from 'react';
     2→import { createPortal } from 'react-dom';
     3→import { Button } from '../atoms/Button';
     4→import { Icon } from '../atoms/Icon';
     5→
     6→export type ModalSize = 'sm' | 'md' | 'lg' | 'xl' | 'full';
     7→
     8→export interface ModalProps {
     9→  isOpen: boolean;
    10→  onClose: () => void;
    11→  title?: string;
    12→  children: ReactNode;
    13→  size?: ModalSize;
    14→  showCloseButton?: boolean;
    15→  closeOnOverlayClick?: boolean;
    16→  closeOnEscape?: boolean;
    17→  footer?: ReactNode;
    18→  className?: string;
    19→}
    20→
    21→const sizeStyles: Record<ModalSize, string> = {
    22→  sm: 'max-w-sm',
    23→  md: 'max-w-md',
    24→  lg: 'max-w-lg',
    25→  xl: 'max-w-xl',
    26→  full: 'max-w-[90vw] max-h-[90vh]',
    27→};
    28→
    29→export function Modal({
    30→  isOpen,
    31→  onClose,
    32→  title,
    33→  children,
    34→  size = 'md',
    35→  showCloseButton = true,
    36→  closeOnOverlayClick = true,
    37→  closeOnEscape = true,
    38→  footer,
    39→  className = '',
    40→}: ModalProps) {
    41→  const modalRef = useRef<HTMLDivElement>(null);
    42→  const previousActiveElement = useRef<HTMLElement | null>(null);
    43→
    44→  // Handle escape key
    45→  useEffect(() => {
    46→    if (!isOpen || !closeOnEscape) return;
    47→
    48→    const handleKeyDown = (e: globalThis.KeyboardEvent) => {
    49→      if (e.key === 'Escape') {
    50→        onClose();
    51→      }
    52→    };
    53→
    54→    document.addEventListener('keydown', handleKeyDown);
    55→    return () => document.removeEventListener('keydown', handleKeyDown);
    56→  }, [isOpen, closeOnEscape, onClose]);
    57→
    58→  // Focus trap and body scroll lock
    59→  useEffect(() => {
    60→    if (isOpen) {
    61→      previousActiveElement.current = document.activeElement as HTMLElement;
    62→      modalRef.current?.focus();
    63→      document.body.style.overflow = 'hidden';
    64→    } else {
    65→      document.body.style.overflow = '';
    66→      previousActiveElement.current?.focus();
    67→    }
    68→
    69→    return () => {
    70→      document.body.style.overflow = '';
    71→    };
    72→  }, [isOpen]);
    73→
    74→  // Handle focus trap
    75→  const handleKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    76→    if (e.key !== 'Tab') return;
    77→
    78→    const focusableElements = modalRef.current?.querySelectorAll(
    79→      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    80→    );
    81→
    82→    if (!focusableElements || focusableElements.length === 0) return;
    83→
    84→    const firstElement = focusableElements[0] as HTMLElement;
    85→    const lastElement = focusableElements[focusableElements.length - 1] as HTMLElement;
    86→
    87→    if (e.shiftKey && document.activeElement === firstElement) {
    88→      e.preventDefault();
    89→      lastElement.focus();
    90→    } else if (!e.shiftKey && document.activeElement === lastElement) {
    91→      e.preventDefault();
    92→      firstElement.focus();
    93→    }
    94→  };
    95→
    96→  if (!isOpen) return null;
    97→
    98→  const modal = (
    99→    <div
   100→      className="fixed inset-0 z-50 flex items-center justify-center p-4"
   101→      role="presentation"
   102→    >
   103→      {/* Overlay */}
   104→      <div
   105→        className="absolute inset-0 bg-black/60 backdrop-blur-sm animate-fade-in"
   106→        onClick={closeOnOverlayClick ? onClose : undefined}
   107→        aria-hidden="true"
   108→      />
   109→
   110→      {/* Modal content */}
   111→      <div
   112→        ref={modalRef}
   113→        role="dialog"
   114→        aria-modal="true"
   115→        aria-labelledby={title ? 'modal-title' : undefined}
   116→        tabIndex={-1}
   117→        onKeyDown={handleKeyDown}
   118→        className={`
   119→          relative w-full ${sizeStyles[size]}
   120→          bg-surface-800 rounded-xl
   121→          border border-surface-700
   122→          shadow-2xl
   123→          animate-scale-in
   124→          ${className}
   125→        `}
   126→      >
   127→        {/* Header */}
   128→        {(title || showCloseButton) && (
   129→          <div className="flex items-center justify-between px-6 py-4 border-b border-surface-700">
   130→            {title && (
   131→              <h2 id="modal-title" className="text-lg font-semibold text-surface-100">
   132→                {title}
   133→              </h2>
   134→            )}
   135→            {showCloseButton && (
   136→              <button
   137→                onClick={onClose}
   138→                className="
   139→                  p-1.5 -mr-1.5
   140→                  text-surface-400 hover:text-surface-200
   141→                  hover:bg-surface-700 rounded-lg
   142→                  transition-colors duration-150
   143→                  focus:outline-none focus-visible:ring-2 focus-visible:ring-primary-500/50
   144→                "
   145→                aria-label="Close modal"
   146→              >
   147→                <Icon name="close" size="md" />
   148→              </button>
   149→            )}
   150→          </div>
   151→        )}
   152→
   153→        {/* Body */}
   154→        <div className="px-6 py-4 max-h-[60vh] overflow-y-auto">
   155→          {children}
   156→        </div>
   157→
   158→        {/* Footer */}
   159→        {footer && (
   160→          <div className="px-6 py-4 border-t border-surface-700 flex items-center justify-end gap-3">
   161→            {footer}
   162→          </div>
   163→        )}
   164→      </div>
   165→    </div>
   166→  );
   167→
   168→  return createPortal(modal, document.body);
   169→}
   170→
   171→// Confirmation modal helper
   172→export interface ConfirmModalProps {
   173→  isOpen: boolean;
   174→  onClose: () => void;
   175→  onConfirm: () => void;
   176→  title?: string;
   177→  message: string;
   178→  confirmLabel?: string;
   179→  cancelLabel?: string;
   180→  variant?: 'default' | 'danger';
   181→  isLoading?: boolean;
   182→}
   183→
   184→export function ConfirmModal({
   185→  isOpen,
   186→  onClose,
   187→  onConfirm,
   188→  title = 'Confirm',
   189→  message,
   190→  confirmLabel = 'Confirm',
   191→  cancelLabel = 'Cancel',
   192→  variant = 'default',
   193→  isLoading = false,
   194→}: ConfirmModalProps) {
   195→  return (
   196→    <Modal
   197→      isOpen={isOpen}
   198→      onClose={onClose}
   199→      title={title}
   200→      size="sm"
