     1→import { useState, useEffect } from 'react';
     2→import { useWebSocket } from './hooks/useWebSocket';
     3→import {
     4→  startBackend,
     5→  stopBackend,
     6→  getBackendStatus,
     7→  healthCheck,
     8→  getBackendInfo,
     9→  pingBackend,
    10→  type BackendStatus,
    11→  type BackendInfo
    12→} from './services/backend';
    13→
    14→function App() {
    15→  const [backendStatus, setBackendStatus] = useState<BackendStatus | null>(null);
    16→  const [backendInfo, setBackendInfo] = useState<BackendInfo | null>(null);
    17→  const [isLoading, setIsLoading] = useState(false);
    18→  const [error, setError] = useState<string | null>(null);
    19→  const [pingResult, setPingResult] = useState<string | null>(null);
    20→
    21→  const { isConnected, lastMessage, sendMessage, connect, disconnect } = useWebSocket();
    22→
    23→  // Check backend status on mount
    24→  useEffect(() => {
    25→    const checkStatus = async () => {
    26→      try {
    27→        const status = await getBackendStatus();
    28→        setBackendStatus(status);
    29→      } catch (err) {
    30→        console.error('Failed to get backend status:', err);
    31→      }
    32→    };
    33→    checkStatus();
    34→  }, []);
    35→
    36→  const handleStartBackend = async () => {
    37→    setIsLoading(true);
    38→    setError(null);
    39→    try {
    40→      const status = await startBackend();
    41→      setBackendStatus(status);
    42→
    43→      // Wait a bit then get backend info
    44→      await new Promise(resolve => setTimeout(resolve, 1000));
    45→      try {
    46→        const info = await getBackendInfo();
    47→        setBackendInfo(info);
    48→      } catch {
    49→        console.log('Backend info not available yet');
    50→      }
    51→    } catch (err) {
    52→      setError(err instanceof Error ? err.message : 'Failed to start backend');
    53→    } finally {
    54→      setIsLoading(false);
    55→    }
    56→  };
    57→
    58→  const handleStopBackend = async () => {
    59→    setIsLoading(true);
    60→    setError(null);
    61→    try {
    62→      await stopBackend();
    63→      setBackendStatus({ running: false, port: null });
    64→      setBackendInfo(null);
    65→      disconnect();
    66→    } catch (err) {
    67→      setError(err instanceof Error ? err.message : 'Failed to stop backend');
    68→    } finally {
    69→      setIsLoading(false);
    70→    }
    71→  };
    72→
    73→  const handleHealthCheck = async () => {
    74→    try {
    75→      const result = await healthCheck();
    76→      setError(null);
    77→      setPingResult(`Health: ${result.status} at ${result.timestamp}`);
    78→    } catch (err) {
    79→      setError(err instanceof Error ? err.message : 'Health check failed');
    80→    }
    81→  };
    82→
    83→  const handlePing = async () => {
    84→    try {
    85→      const result = await pingBackend();
    86→      setError(null);
    87→      setPingResult(`API Ping: ${result.message} at ${result.timestamp}`);
    88→    } catch (err) {
    89→      setError(err instanceof Error ? err.message : 'Ping failed');
    90→    }
    91→  };
    92→
    93→  const handleWebSocketPing = () => {
    94→    sendMessage({ type: 'ping' });
    95→  };
    96→
    97→  const handleWebSocketEcho = () => {
    98→    sendMessage({ type: 'echo', data: 'Hello from React!' });
    99→  };
   100→
   101→  return (
   102→    <div className="min-h-screen bg-surface-900 text-white p-8">
   103→      <div className="max-w-4xl mx-auto">
   104→        <header className="mb-8">
   105→          <h1 className="text-4xl font-bold text-primary-400 mb-2">ScreenToGif</h1>
   106→          <p className="text-surface-400">React + Tauri + C# Backend</p>
   107→        </header>
   108→
   109→        {error && (
   110→          <div className="bg-red-900/50 border border-red-500 text-red-200 px-4 py-3 rounded-lg mb-6">
   111→            {error}
   112→          </div>
   113→        )}
   114→
   115→        {/* Backend Status Card */}
   116→        <div className="bg-surface-800 rounded-xl p-6 mb-6 border border-surface-700">
   117→          <h2 className="text-xl font-semibold mb-4 text-primary-300">Backend Status</h2>
   118→
   119→          <div className="flex items-center gap-4 mb-4">
   120→            <div className={`w-3 h-3 rounded-full ${backendStatus?.running ? 'bg-green-500' : 'bg-red-500'}`} />
   121→            <span className="text-surface-300">
   122→              {backendStatus?.running ? `Running on port ${backendStatus.port}` : 'Not running'}
   123→            </span>
   124→          </div>
   125→
   126→          {backendInfo && (
   127→            <div className="bg-surface-900 rounded-lg p-4 mb-4 font-mono text-sm">
   128→              <p><span className="text-surface-500">Name:</span> {backendInfo.name}</p>
   129→              <p><span className="text-surface-500">Version:</span> {backendInfo.version}</p>
   130→              <p><span className="text-surface-500">Platform:</span> {backendInfo.platform}</p>
