/**
 * UI Store
 * Manages global UI state: modals, toasts, sidebar, loading states
 */

import { create } from 'zustand';
import { subscribeWithSelector } from 'zustand/middleware';

/** Toast notification types */
export type ToastType = 'info' | 'success' | 'warning' | 'error';

/** Toast notification */
export interface Toast {
  id: string;
  type: ToastType;
  title: string;
  message?: string;
  duration?: number; // milliseconds, 0 = persistent
  action?: {
    label: string;
    onClick: () => void;
  };
  dismissible: boolean;
  createdAt: number;
}

/** Modal types in the application */
export type ModalType =
  | 'settings'
  | 'about'
  | 'newProject'
  | 'openProject'
  | 'saveProject'
  | 'exportOptions'
  | 'hotkeys'
  | 'updateAvailable'
  | 'unsavedChanges'
  | 'deleteConfirm'
  | 'feedback'
  | 'license'
  | 'changelog'
  | 'regionSelector'
  | 'webcamPreview'
  | 'customFrameDelay'
  | 'batchEdit'
  | 'imageEffects'
  | 'textOverlay'
  | 'watermark'
  | 'border'
  | 'resize'
  | 'crop';

/** Modal state */
export interface ModalState {
  type: ModalType;
  isOpen: boolean;
  data?: unknown;
  onClose?: () => void;
  onConfirm?: () => void;
}

/** Active view/page in the application */
export type AppView = 'startup' | 'recorder' | 'editor' | 'webcam' | 'board' | 'settings';

/** Panel types */
export type PanelId = 'sidebar' | 'timeline' | 'properties' | 'preview';

interface UIState {
  // Current view
  currentView: AppView;
  previousView: AppView | null;

  // Modals
  openModals: ModalState[];

  // Toasts
  toasts: Toast[];
  maxToasts: number;

  // Panels

